insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'conclusion',1,'Sixteen indexed records from seven companions report the statement: Abū Hurayra 7, Jābir 3, Ibn Masʿūd 2, and one each from Anas, Abū Saʿīd, Abū Juḥayfa and Ibn ʿAbbās.',array['bukhari:6993','bukhari:6994','muslim:2268a','tirmidhi:2276','ibnmajah:3903','ibnmajah:3904','ibnmajah:3905']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'conclusion',2,'Three outcomes are worded: "he has seen me" (most routes); "he will see me while awake" (al-Zuhrī ← Abū Salama ← Abū Hurayra: Bukhārī 6993, Muslim 2266b, Abū Dāwūd 5023); and "as if he saw me awake" (Abū Juḥayfa). In Muslim 2266b and Abū Dāwūd 5023 the narrator is himself unsure between "will see me" and "as if he saw me". These are kept as lexical variants, not contradictions.',array['bukhari:6993','muslim:2266b','abudawud:5023','ibnmajah:3904','muslim:2266a']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'conclusion',3,'Every report gives the reason "Satan cannot take my form", worded as yatamaththalu, yatakhayyalu, yatashabbahu or "cannot".',array['muslim:2266a','bukhari:6994','muslim:2268b','ibnmajah:3904']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'conclusion',4,'Within the Abū Hurayra branch the routes spread through at least four successors: Abū Ṣāliḥ, Abū Salama, Ibn Sīrīn and ʿAbd al-Raḥmān b. Yaʿqūb. Abū Hurayra himself is the branch common link. Bukhārī 6993 adds Ibn Sīrīn’s gloss "if he sees him in his (true) form".',array['bukhari:110','bukhari:6993','muslim:2266a','ibnmajah:3901']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,citations,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'conclusion',5,'Bukhārī 110 / 6197 combine this clause with the lying warning and the name/kunya ruling (Abū Ḥuṣayn ← Abū Ṣāliḥ). The same records are members of the lying-about-the-Prophet family.',array['bukhari:110','bukhari:6197']::text[],'grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'uncertainty',1,'The isnad of Ibn Mājah 3905 as stored ("Abū ʿAwāna ḥaddathanā ʿan Jābir ʿan ʿAmmār") is disordered; the position of "Jābir" is uncertain.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'uncertainty',2,'Muslim 2266 and 2268 have further sub-numbers on sunnah.com that the corpus does not hold.','grok-bot') on conflict do nothing;
insert into public.hadith_family_conclusions(family_id,kind,ordinal,body,authored_by) values ((select id from public.hadith_families where slug='seeing-the-prophet-in-a-dream'),'uncertainty',3,'Several identifications (Hishām = Ibn Ḥassān, Rawḥ = Ibn ʿUbāda, Sufyān = al-Thawrī) are proposals.','grok-bot') on conflict do nothing;
